package io.github.describeadmin.codegen;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class CodegenCliMutaGate1Test {

    @TempDir
    Path tmp;

    private int runCli(String[] args, StringBuilder captured) throws IOException {
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        PrintStream ps = new PrintStream(buf, true, StandardCharsets.UTF_8);
        int code = CodegenCli.run(args, ps);
        ps.flush();
        captured.append(buf.toString(StandardCharsets.UTF_8));
        return code;
    }

    @Test
    void earlyExitPathsReturnExpectedCodesAndOutput() throws IOException {
        // no args: usage + exit code 1
        StringBuilder noArgs = new StringBuilder();
        assertEquals(1, runCli(new String[0], noArgs));
        assertTrue(noArgs.toString().contains("codegen <spec.yaml>"));
        assertTrue(noArgs.toString().contains("--dry-run"));

        // -h and --help: usage + exit code 0
        StringBuilder shortHelp = new StringBuilder();
        assertEquals(0, runCli(new String[]{"-h"}, shortHelp));
        assertTrue(shortHelp.toString().contains("--force"));
        assertTrue(shortHelp.toString().contains("--frontend-out"));

        StringBuilder longHelp = new StringBuilder();
        assertEquals(0, runCli(new String[]{"--help"}, longHelp));
        assertTrue(longHelp.toString().contains("--layout"));

        // unknown option: reported, usage printed, exit code 1 (checked before spec existence)
        StringBuilder unknown = new StringBuilder();
        Path missingSpec = tmp.resolve("nope.yaml");
        assertEquals(1, runCli(new String[]{missingSpec.toString(), "--bogus"}, unknown));
        assertTrue(unknown.toString().startsWith("\u2717 "));
        assertTrue(unknown.toString().contains("--bogus"));
        assertTrue(unknown.toString().contains("codegen <spec.yaml>"));

        // missing spec file: error with absolute path, exit code 1, nothing written
        Path outDir = tmp.resolve("out");
        StringBuilder missing = new StringBuilder();
        assertEquals(1, runCli(new String[]{missingSpec.toString(), "--out", outDir.toString()}, missing));
        assertTrue(missing.toString().startsWith("\u2717 "));
        assertTrue(missing.toString().contains(missingSpec.toAbsolutePath().toString()));
        assertFalse(missing.toString().contains("codegen <spec.yaml>"));
        assertFalse(Files.exists(outDir));
    }
}

package io.github.describeadmin.codegen;

import io.github.describeadmin.codegen.generator.DdlGenerator;
import io.github.describeadmin.codegen.generator.JavaGenerator;
import io.github.describeadmin.codegen.generator.MenuSqlGenerator;
import io.github.describeadmin.codegen.generator.VueGenerator;
import io.github.describeadmin.codegen.model.Layout;
import io.github.describeadmin.codegen.model.ModuleSpec;
import org.junit.jupiter.api.Test;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;

class CodegenCliMutaGate2Test {

    @Test
    void planProducesEightFilesInOrderWithExpectedPathsAndContents() {
        ModuleSpec s = new ModuleSpec("com.example.app", "product", "Product", "product_info",
                "商品", "/api/product", Layout.NESTED, "spec", List.of());
        Path out = Path.of("outRoot");
        Path fe = Path.of("elsewhere", "webapp");

        Map<Path, String> files = CodegenCli.plan(s, out, fe);

        Path java = out.resolve("src/main/java");
        Path db = out.resolve("src/main/resources/db");
        List<Path> expectedKeys = new ArrayList<>();
        expectedKeys.add(java.resolve(s.packageOf("entity").replace('.', '/')).resolve(s.entityClass() + ".java"));
        expectedKeys.add(java.resolve(s.packageOf("mapper").replace('.', '/')).resolve(s.mapperClass() + ".java"));
        expectedKeys.add(java.resolve(s.packageOf("service").replace('.', '/')).resolve(s.serviceClass() + ".java"));
        expectedKeys.add(java.resolve(s.packageOf("controller").replace('.', '/')).resolve(s.controllerClass() + ".java"));
        expectedKeys.add(db.resolve("schema-product_info.sql"));
        expectedKeys.add(db.resolve("menu-product_info.sql"));
        expectedKeys.add(fe.resolve("src/api").resolve("product.ts"));
        expectedKeys.add(fe.resolve("src/views").resolve("product").resolve("index.vue"));

        assertEquals(expectedKeys, new ArrayList<>(files.keySet()));

        List<String> expectedValues = List.of(
                JavaGenerator.entity(s),
                JavaGenerator.mapper(s),
                JavaGenerator.service(s),
                JavaGenerator.controller(s),
                DdlGenerator.generate(s),
                MenuSqlGenerator.generate(s),
                VueGenerator.api(s),
                VueGenerator.page(s));
        assertEquals(expectedValues, new ArrayList<>(files.values()));
    }
}

package io.github.describeadmin.codegen;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class CodegenCliMutaGate3Test {

    private static final class Result {
        final int exit;
        final String output;

        Result(int exit, String output) {
            this.exit = exit;
            this.output = output;
        }
    }

    private static Result runMain(String... args) throws IOException, InterruptedException {
        String javaBin = Path.of(System.getProperty("java.home"), "bin", "java").toString();
        List<String> cmd = new ArrayList<>();
        cmd.add(javaBin);
        cmd.add("-cp");
        cmd.add(System.getProperty("java.class.path"));
        cmd.add(CodegenCli.class.getName());
        for (String a : args) {
            cmd.add(a);
        }
        Process p = new ProcessBuilder(cmd).redirectErrorStream(true).start();
        byte[] bytes = p.getInputStream().readAllBytes();
        assertTrue(p.waitFor(60, TimeUnit.SECONDS), "child process timed out");
        return new Result(p.exitValue(), new String(bytes, StandardCharsets.UTF_8));
    }

    @Test
    void mainPropagatesRunResultAsProcessExitCode(@TempDir Path tmp) throws Exception {
        // --help: run returns 0, main must exit with 0 and print usage
        Result help = runMain("--help");
        assertEquals(0, help.exit, help.output);
        assertTrue(help.output.contains("codegen"), help.output);

        // missing spec file: run returns 1, main exits with 1 and prints the failure marker
        Path missing = tmp.resolve("no-such-spec.yaml");
        Result missingSpec = runMain(missing.toString());
        assertEquals(1, missingSpec.exit, missingSpec.output);
        assertTrue(missingSpec.output.contains("\u2717 Spec "), missingSpec.output);
        assertTrue(missingSpec.output.contains("no-such-spec.yaml"), missingSpec.output);
    }
}

package io.github.describeadmin.codegen;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.stream.Stream;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class CodegenCliMutaGate4Test {

    private static String capture(int[] codeHolder, String... args) throws IOException {
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        PrintStream ps = new PrintStream(buf, true, StandardCharsets.UTF_8);
        codeHolder[0] = CodegenCli.run(args, ps);
        ps.flush();
        return buf.toString(StandardCharsets.UTF_8);
    }

    @Test
    void earlyExitPathsReturnExpectedCodesAndMessages(@TempDir Path tmp) throws IOException {
        int[] code = new int[1];

        // no args: usage, exit code 1
        String text = capture(code);
        assertEquals(1, code[0]);
        assertTrue(text.contains("用法:"));
        assertTrue(text.contains("--dry-run"));

        // --help: usage, exit code 0
        text = capture(code, "--help");
        assertEquals(0, code[0]);
        assertTrue(text.contains("用法:"));

        // -h: usage, exit code 0
        text = capture(code, "-h");
        assertEquals(0, code[0]);
        assertTrue(text.contains("用法:"));

        // unknown option: error + usage, exit code 1 (spec existence not yet checked)
        text = capture(code, tmp.resolve("whatever.yaml").toString(), "--bogus");
        assertEquals(1, code[0]);
        assertTrue(text.contains("✗ 未知参数: --bogus"));
        assertTrue(text.contains("用法:"));

        // missing spec file: error with absolute path, exit code 1, no usage, nothing written
        Path missing = tmp.resolve("missing.yaml");
        Path outDir = tmp.resolve("out");
        text = capture(code, missing.toString(), "--out", outDir.toString(), "--force");
        assertEquals(1, code[0]);
        assertTrue(text.contains("✗ Spec 文件不存在: " + missing.toAbsolutePath()));
        assertFalse(text.contains("用法:"));
        assertFalse(Files.exists(outDir));

        try (Stream<Path> children = Files.list(tmp)) {
            assertEquals(0, children.count());
        }
    }
}

