package io.github.describeadmin.codegen;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.util.List;
import java.util.concurrent.TimeUnit;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class CodegenCliMutaGate6Test {

    @TempDir
    Path tmp;

    private static final class Result {
        final int exit;
        final String output;

        Result(int exit, String output) {
            this.exit = exit;
            this.output = output;
        }
    }

    private Result runMain(String... args) throws Exception {
        String java = Path.of(System.getProperty("java.home"), "bin", "java").toString();
        List<String> cmd = new java.util.ArrayList<>();
        cmd.add(java);
        cmd.add("-cp");
        cmd.add(System.getProperty("java.class.path"));
        cmd.add(CodegenCli.class.getName());
        cmd.addAll(List.of(args));

        ProcessBuilder pb = new ProcessBuilder(cmd);
        pb.redirectErrorStream(true);
        pb.directory(tmp.toFile());
        Process p = pb.start();
        byte[] bytes = p.getInputStream().readAllBytes();
        boolean finished = p.waitFor(60, TimeUnit.SECONDS);
        if (!finished) {
            p.destroyForcibly();
            throw new IllegalStateException("child process timed out");
        }
        return new Result(p.exitValue(), new String(bytes, StandardCharsets.UTF_8));
    }

    @Test
    void mainExitsWithCodeMatchingOutcomeAndPrintsUtf8Output() throws Exception {
        // --help: exit code 0 and usage text in UTF-8
        Result help = runMain("--help");
        assertEquals(0, help.exit, help.output);
        assertTrue(help.output.contains("用法"), help.output);
        assertTrue(help.output.contains("--dry-run"), help.output);

        // no arguments: usage printed but exit code 1
        Result none = runMain();
        assertEquals(1, none.exit, none.output);
        assertTrue(none.output.contains("用法"), none.output);

        // missing spec file: error message and exit code 1, nothing written
        String missing = tmp.resolve("does-not-exist.yaml").toString();
        Result bad = runMain(missing);
        assertEquals(1, bad.exit, bad.output);
        assertTrue(bad.output.contains("✗ Spec 文件不存在"), bad.output);
        assertTrue(bad.output.contains("does-not-exist.yaml"), bad.output);
        File[] left = tmp.toFile().listFiles();
        assertEquals(0, left == null ? 0 : left.length);
    }
}

