package io.github.describeadmin.codegen;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.util.concurrent.TimeUnit;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class CodegenCliMutaGate9Test {

    @Test
    void mainExitsWithOneAndPrintsUtf8MessageWhenSpecFileIsMissing(@TempDir Path tmp) throws Exception {
        Path missing = tmp.resolve("does-not-exist.yaml");
        Path outDir = tmp.resolve("out");

        String javaBin = Path.of(System.getProperty("java.home"), "bin", "java").toString();
        ProcessBuilder pb = new ProcessBuilder(
                javaBin,
                "-cp", System.getProperty("java.class.path"),
                CodegenCli.class.getName(),
                missing.toString(),
                "--out", outDir.toString());
        pb.redirectErrorStream(true);

        Process process = pb.start();
        byte[] bytes = process.getInputStream().readAllBytes();
        boolean finished = process.waitFor(60, TimeUnit.SECONDS);
        if (!finished) {
            process.destroyForcibly();
        }
        assertTrue(finished, "child JVM should terminate");

        String output = new String(bytes, StandardCharsets.UTF_8);

        assertEquals(1, process.exitValue(), "missing spec must yield exit code 1, output: " + output);
        assertTrue(output.contains("✗ Spec 文件不存在: " + missing.toAbsolutePath()),
                "output should report the missing spec in UTF-8, was: " + output);
        assertFalse(new File(outDir.toString()).exists(), "nothing should be generated");
    }
}

