package io.github.describeadmin.codegen;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.util.concurrent.TimeUnit;

import org.junit.jupiter.api.Test;

class CodegenCliMutaGate12Test {

    @Test
    void mainReportsUnexpectedExceptionWithClassNameAndExitsWithCodeOne() throws Exception {
        String javaBin = Path.of(System.getProperty("java.home"), "bin", "java").toString();
        String classpath = System.getProperty("java.class.path");

        // "--out" without a value triggers an ArrayIndexOutOfBoundsException inside run(),
        // which main() must catch via the generic handler.
        ProcessBuilder pb = new ProcessBuilder(
                javaBin, "-cp", classpath,
                "io.github.describeadmin.codegen.CodegenCli",
                "spec.yaml", "--out");
        pb.redirectErrorStream(true);

        Process process = pb.start();
        byte[] bytes;
        try (InputStream in = process.getInputStream()) {
            bytes = in.readAllBytes();
        }
        boolean finished = process.waitFor(60, TimeUnit.SECONDS);
        if (!finished) {
            process.destroyForcibly();
        }
        assertTrue(finished, "process should finish in time");

        String output = new String(bytes, StandardCharsets.UTF_8);

        assertEquals(1, process.exitValue(), "generic exceptions must map to exit code 1");
        assertTrue(output.contains("✗ ArrayIndexOutOfBoundsException"),
                "output should name the exception class, was: " + output);
    }
}

