            cmd.add(a);
        }
        ProcessBuilder pb = new ProcessBuilder(cmd);
        pb.redirectErrorStream(true);
        Process p = pb.start();
        byte[] bytes = p.getInputStream().readAllBytes();
        assertTrue(p.waitFor(60, TimeUnit.SECONDS), "subprocess timed out");
        return new Result(p.exitValue(), new String(bytes, StandardCharsets.UTF_8));
    }

    @Test
    void mainMapsOutcomesToExitCodesAndReportsUnexpectedExceptions() throws Exception {
        // --help: normal completion, exit code 0
        Result help = runMain("--help");
