        assertTrue(help.output.contains("--dry-run"), help.output);

        // Dangling option value: ArrayIndexOutOfBoundsException is caught by the
        // generic handler -> exit code 1 with class simple name in the message
        Result dangling = runMain("some-spec.yaml", "--out");
        assertEquals(1, dangling.exit, dangling.output);
        assertTrue(dangling.output.contains("\u2717 ArrayIndexOutOfBoundsException:"),
                dangling.output);
    }
