package io.github.describeadmin.codegen;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class CodegenCliMutaGate45Test {

    private static final class Result {
        final int exit;
        final String output;

        Result(int exit, String output) {
            this.exit = exit;
            this.output = output;
        }
    }

    private static Result runMain(String... args) throws IOException, InterruptedException {
        List<String> cmd = new ArrayList<>();
        cmd.add(Path.of(System.getProperty("java.home"), "bin", "java").toString());
        cmd.add("-cp");
        cmd.add(System.getProperty("java.class.path"));
        cmd.add(CodegenCli.class.getName());
        for (String a : args) {
            cmd.add(a);
        }
        Process p = new ProcessBuilder(cmd).redirectErrorStream(true).start();
        p.getOutputStream().close();
        String output = new String(p.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
        int exit = p.waitFor();
        return new Result(exit, output);
    }

    @Test
    void mainPropagatesRunResultAsExitCode(@TempDir Path tmp) throws Exception {
        Path missing = tmp.resolve("no-such-spec.yaml");

        Result notFound = runMain(missing.toString());
        assertEquals(1, notFound.exit);
        assertTrue(notFound.output.contains("✗ Spec 文件不存在"), notFound.output);

        Result help = runMain("--help");
        assertEquals(0, help.exit);
        assertTrue(help.output.contains("用法:"), help.output);

        Result noArgs = runMain();
        assertEquals(1, noArgs.exit);
        assertTrue(noArgs.output.contains("用法:"), noArgs.output);
    }
}
